<?php ob_start(); ?><h1><?= e(t('Signatures')) ?></h1><form><select class="input" name="enabled"><option value=""><?= e(t('Any status')) ?></option><option value="1" <?= ($_GET['enabled']??'')==='1'?'selected':'' ?>><?= e(t('enabled')) ?></option><option value="0" <?= ($_GET['enabled']??'')==='0'?'selected':'' ?>><?= e(t('disabled')) ?></option></select> <input class="input" name="risk" placeholder="<?= e(t('risk')) ?>" value="<?= e($_GET['risk']??'') ?>"> <input class="input" name="type" placeholder="<?= e(t('type')) ?>" value="<?= e($_GET['type']??'') ?>"> <input class="input" name="source" placeholder="<?= e(t('source')) ?>" value="<?= e($_GET['source']??'') ?>"> <button class="btn"><?= e(t('Filter')) ?></button> <a class="btn" href="/signatures/create"><?= e(t('Create manual signature')) ?></a></form><table><tr><th><?= e(t('ID')) ?></th><th><?= e(t('Name')) ?></th><th><?= e(t('Risk')) ?></th><th><?= e(t('Type')) ?></th><th><?= e(t('Pattern')) ?></th><th><?= e(t('Source')) ?></th><th><?= e(t('Enabled')) ?></th><th><?= e(t('Actions')) ?></th></tr><?php foreach($signatures as $s): ?><tr><td><?= e($s['id']) ?></td><td><a href="/signatures/<?= e($s['id']) ?>"><?= e($s['name']) ?></a></td><td><span class="badge <?= e($s['risk']) ?>"><?= e(t($s['risk'])) ?></span></td><td><?= e($s['type']) ?></td><td><?= e($s['pattern_type']) ?></td><td><?= e($s['source']) ?></td><td><?= $s['enabled']?e(t('yes')):e(t('no')) ?></td><td><form method="post" action="/signatures/toggle" style="display:inline"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="btn small"><?= $s['enabled']?e(t('Disable')):e(t('Enable')) ?></button></form> <form method="post" action="/signatures/duplicate" style="display:inline"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="btn small"><?= e(t('Duplicate')) ?></button></form> <form method="post" action="/signatures/delete" style="display:inline" onsubmit="return confirm(<?= e(json_encode(t('Delete signature?'))) 